class CarsFilterModal{constructor(){this.modal=null;this.isOpen=false;this.hasShownOnLoad=false;this.touchStartY=0;this.touchEndY=0;this.priceFilterSettings={economy:{min:0,max:30},standard:{min:31,max:60},premium:{min:61,max:999}};this.init()}async init(){await this.loadPriceFilterSettings();this.createModal();this.bindEvents();this.setupLanguageChangeListener()}async loadPriceFilterSettings(){try{const response=await fetch(`${window.API_BASE_URL}/api/fee-settings/public`);if(response.ok){const feeSettings=await response.json();this.priceFilterSettings={economy:{min:feeSettings.economy_price_min,max:feeSettings.economy_price_max},standard:{min:feeSettings.standard_price_min,max:feeSettings.standard_price_max},premium:{min:feeSettings.premium_price_min,max:feeSettings.premium_price_max}}}}catch(error){console.error("Error loading price filter settings:",error)}}updateModalDescriptions(){if(!this.modal){return}const currentLang=localStorage.getItem("lang")||"ro";const economDesc=this.modal.querySelector(".filter-card.econom .filter-card-description");if(economDesc){const maxPrice=this.priceFilterSettings.economy.max;let text="";if(currentLang==="ro"){text=`Mașini până la ${maxPrice} EUR`}else if(currentLang==="ru"){text=`Автомобили до ${maxPrice} EUR`}else{text=`Cars up to ${maxPrice} EUR`}economDesc.textContent=text;economDesc.setAttribute("data-i18n","")}const standardDesc=this.modal.querySelector(".filter-card.standard .filter-card-description");if(standardDesc){const minPrice=this.priceFilterSettings.standard.min;const maxPrice=this.priceFilterSettings.standard.max;let text="";if(currentLang==="ro"){text=`Mașini între ${minPrice}-${maxPrice} EUR`}else if(currentLang==="ru"){text=`Автомобили от ${minPrice} до ${maxPrice} EUR`}else{text=`Cars between ${minPrice}-${maxPrice} EUR`}standardDesc.textContent=text;standardDesc.setAttribute("data-i18n","")}const premiumDesc=this.modal.querySelector(".filter-card.premium .filter-card-description");if(premiumDesc){const minPrice=this.priceFilterSettings.premium.min;let text="";if(currentLang==="ro"){text=`Mașini ${minPrice} EUR și peste`}else if(currentLang==="ru"){text=`Автомобили от ${minPrice} EUR и выше`}else{text=`Cars ${minPrice} EUR and above`}premiumDesc.textContent=text;premiumDesc.setAttribute("data-i18n","")}}setupLanguageChangeListener(){document.addEventListener("languageChanged",()=>{setTimeout(()=>{this.updateModalDescriptions()},200)});if(typeof i18next!=="undefined"){i18next.on("languageChanged",()=>{setTimeout(()=>{this.updateModalDescriptions()},200)})}this.setupContentWatcher();this.setupPeriodicUpdates()}setupPeriodicUpdates(){this.priceUpdateInterval=setInterval(()=>{if(this.modal&&this.isOpen){const descriptions=this.modal.querySelectorAll(".filter-card-description");let needsUpdate=false;descriptions.forEach(desc=>{if(desc.textContent.includes("{{")||desc.textContent.includes("}}")){needsUpdate=true}});if(needsUpdate){this.updateModalDescriptions()}}},500)}setupContentWatcher(){if(!this.modal)return;const observer=new MutationObserver(mutations=>{let shouldUpdate=false;mutations.forEach(mutation=>{if(mutation.type==="childList"||mutation.type==="characterData"){const target=mutation.target;if(target.classList&&target.classList.contains("filter-card-description")){if(target.textContent.includes("{{")||target.textContent.includes("}}")){shouldUpdate=true}}}});if(shouldUpdate){this.updateModalDescriptions()}});observer.observe(this.modal,{childList:true,subtree:true,characterData:true});this.contentObserver=observer}createModal(){const modalHTML=`\n      <div id="cars-filter-modal" class="filter-modal-overlay">\n        <div class="filter-modal-container">\n          <div class="filter-modal-header">\n            <div class="header-content">\n              <h2 data-i18n="cars.filter_modal_title">Choose Your Car Category</h2>\n              <p data-i18n="cars.filter_modal_subtitle">Select a category to filter our car collection</p>\n            </div>\n            <button class="filter-modal-close" aria-label="Close modal">\n              <i class="fa fa-times"></i>\n            </button>\n          </div>\n          \n          <div class="filter-modal-body">\n            <div class="filter-cards-grid">\n              <div class="filter-card econom" data-filter="econom" tabindex="0" role="button" aria-label="Filter economy cars">\n                <div class="filter-card-content">\n                  <div class="filter-card-icon">\n                    <i class="fa fa-leaf"></i>\n                  </div>\n                  <div class="filter-card-title" data-i18n="cars.filter_econom">Econom</div>\n                  <div class="filter-card-description" data-i18n="cars.filter_econom_desc">Cars up to {{max}} EUR</div>\n                </div>\n              </div>\n              \n              <div class="filter-card standard" data-filter="standard" tabindex="0" role="button" aria-label="Filter standard cars">\n                <div class="filter-card-content">\n                  <div class="filter-card-icon">\n                    <i class="fa fa-car"></i>\n                  </div>\n                  <div class="filter-card-title" data-i18n="cars.filter_standard">Standard</div>\n                  <div class="filter-card-description" data-i18n="cars.filter_standard_desc">Cars between {{min}}-{{max}} EUR</div>\n                </div>\n              </div>\n              \n              <div class="filter-card premium" data-filter="premium" tabindex="0" role="button" aria-label="Filter premium cars">\n                <div class="filter-card-content">\n                  <div class="filter-card-icon">\n                    <i class="fa fa-crown"></i>\n                  </div>\n                  <div class="filter-card-title" data-i18n="cars.filter_premium">Premium</div>\n                  <div class="filter-card-description" data-i18n="cars.filter_premium_desc">Cars {{min}} EUR and above</div>\n                </div>\n              </div>\n              \n              <div class="filter-card all-types" data-filter="all" tabindex="0" role="button" aria-label="Show all car types">\n                <div class="filter-card-content">\n                  <div class="filter-card-icon">\n                    <i class="fa fa-th-large"></i>\n                  </div>\n                  <div class="filter-card-title" data-i18n="cars.filter_all_types">All Types</div>\n                  <div class="filter-card-description" data-i18n="cars.filter_all_types_desc">Show all cars</div>\n                </div>\n              </div>\n            </div>\n          </div>\n          \n          <div class="filter-modal-footer">\n            <p data-i18n="cars.filter_modal_footer">You can change filters anytime using the sidebar</p>\n          </div>\n        </div>\n      </div>\n    `;document.body.insertAdjacentHTML("beforeend",modalHTML);this.modal=document.getElementById("cars-filter-modal")}bindEvents(){if(!this.modal)return;const closeBtn=this.modal.querySelector(".filter-modal-close");if(closeBtn){closeBtn.addEventListener("click",()=>{if(this.isMobile()){this.applyFilter("all")}this.closeModal()})}this.updateModalDescriptions();const filterCards=this.modal.querySelectorAll(".filter-card");filterCards.forEach(card=>{card.addEventListener("click",e=>this.handleCardClick(e,card));card.addEventListener("keydown",e=>this.handleCardKeydown(e,card))});this.modal.addEventListener("click",e=>{if(e.target===this.modal){if(this.isMobile()){this.applyFilter("all");this.closeModal()}else{this.closeModal()}}});document.addEventListener("keydown",e=>{if(e.key==="Escape"&&this.isOpen){if(this.isMobile()){this.applyFilter("all")}this.closeModal()}});this.setupTouchEvents();this.setupScrollLock()}isMobile(){return window.innerWidth<=767}setupTouchEvents(){const modalBody=this.modal.querySelector(".filter-modal-body");const container=this.modal.querySelector(".filter-modal-container");if(!modalBody||!container)return;let startY=0;let currentY=0;let isDragging=false;let isAtTop=false;container.addEventListener("touchstart",e=>{isAtTop=modalBody.scrollTop===0;startY=e.touches[0].clientY;currentY=startY;if(isAtTop){isDragging=true}},{passive:true});container.addEventListener("touchmove",e=>{if(!isDragging)return;currentY=e.touches[0].clientY;const deltaY=currentY-startY;if(deltaY>0&&isAtTop){if(e.cancelable){e.preventDefault()}const translateY=Math.min(deltaY*.5,200);container.style.transform=`translateY(${translateY}px) scale(${1-translateY/1e3})`;container.style.transition="none"}},{passive:false});container.addEventListener("touchend",()=>{if(!isDragging)return;isDragging=false;const deltaY=currentY-startY;if(deltaY>100){this.applyFilter("all");this.closeModal()}else{container.style.transform="";container.style.transition="transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)"}},{passive:true})}setupScrollLock(){const preventScroll=e=>{const modalBody=this.modal.querySelector(".filter-modal-body");if(modalBody&&modalBody.contains(e.target)){return}if(this.isOpen){e.preventDefault();e.stopPropagation()}};document.addEventListener("touchmove",preventScroll,{passive:false});document.addEventListener("wheel",preventScroll,{passive:false});this.preventScrollHandler=preventScroll}handleCardClick(e,card){e.preventDefault();const filterType=card.getAttribute("data-filter");this.applyFilter(filterType);this.closeModal()}handleCardKeydown(e,card){if(e.key==="Enter"||e.key===" "){e.preventDefault();const filterType=card.getAttribute("data-filter");this.applyFilter(filterType);this.closeModal()}}applyFilter(filterType){if(typeof window.applyModalFilter==="function"){window.applyModalFilter(filterType);return}const params=new URLSearchParams(window.location.search);params.delete("min_price");params.delete("max_price");switch(filterType){case"econom":params.set("min_price",this.priceFilterSettings.economy.min);params.set("max_price",this.priceFilterSettings.economy.max);const economyRadio=document.querySelector('input[name="price-category"][value="economy"]');if(economyRadio){document.querySelectorAll('input[name="price-category"]').forEach(r=>r.checked=false);economyRadio.checked=true}break;case"standard":params.set("min_price",this.priceFilterSettings.standard.min);params.set("max_price",this.priceFilterSettings.standard.max);const standardRadio=document.querySelector('input[name="price-category"][value="standard"]');if(standardRadio){document.querySelectorAll('input[name="price-category"]').forEach(r=>r.checked=false);standardRadio.checked=true}break;case"premium":params.set("min_price",this.priceFilterSettings.premium.min);params.set("max_price",this.priceFilterSettings.premium.max);const premiumRadio=document.querySelector('input[name="price-category"][value="premium"]');if(premiumRadio){document.querySelectorAll('input[name="price-category"]').forEach(r=>r.checked=false);premiumRadio.checked=true}break;case"all":const allRadio=document.querySelector('input[name="price-category"][value="all"]');if(allRadio){document.querySelectorAll('input[name="price-category"]').forEach(r=>r.checked=false);allRadio.checked=true}break}const newUrl=window.location.pathname+(params.toString()?"?"+params.toString():"");window.history.pushState({},"",newUrl);this.updateCarList()}clearPriceFilters(){const desktopMinPrice=document.getElementById("filter-price-min");const desktopMaxPrice=document.getElementById("filter-price-max");if(desktopMinPrice)desktopMinPrice.value="";if(desktopMaxPrice)desktopMaxPrice.value="";const mobileMinPrice=document.getElementById("mobile-filter-price-min");const mobileMaxPrice=document.getElementById("mobile-filter-price-max");if(mobileMinPrice)mobileMinPrice.value="";if(mobileMaxPrice)mobileMaxPrice.value=""}setPriceFilter(minPrice,maxPrice){const desktopMinPrice=document.getElementById("filter-price-min");const desktopMaxPrice=document.getElementById("filter-price-max");if(desktopMinPrice){desktopMinPrice.value=minPrice}if(desktopMaxPrice){desktopMaxPrice.value=maxPrice||""}const mobileMinPrice=document.getElementById("mobile-filter-price-min");const mobileMaxPrice=document.getElementById("mobile-filter-price-max");if(mobileMinPrice){mobileMinPrice.value=minPrice}if(mobileMaxPrice){mobileMaxPrice.value=maxPrice||""}}updateCarList(){if(typeof updateFiltersAndFetch==="function"){updateFiltersAndFetch()}else if(typeof fetchAndRenderCars==="function"){fetchAndRenderCars()}else{window.location.reload()}}updateURLAndReload(){const params=new URLSearchParams;const minPrice=document.getElementById("filter-price-min")?.value;const maxPrice=document.getElementById("filter-price-max")?.value;if(minPrice)params.set("min_price",minPrice);if(maxPrice)params.set("max_price",maxPrice);const newUrl=window.location.pathname+(params.toString()?"?"+params.toString():"");window.history.pushState({},"",newUrl);window.location.reload()}openModal(){if(!this.modal||this.isOpen)return;if(typeof updateContent==="function"){updateContent()}this.updateModalDescriptions();document.body.style.overflow="hidden";document.body.style.position="fixed";document.body.style.width="100%";document.body.style.top=`-${window.scrollY}px`;setTimeout(()=>{this.isOpen=true;this.modal.classList.add("active");setTimeout(()=>{const firstCard=this.modal.querySelector(".filter-card");if(firstCard){firstCard.focus()}},300)},50)}closeModal(){if(!this.modal||!this.isOpen)return;this.isOpen=false;this.modal.classList.remove("active");const scrollY=document.body.style.top;document.body.style.overflow="";document.body.style.position="";document.body.style.width="";document.body.style.top="";window.scrollTo(0,parseInt(scrollY||"0")*-1);if(this.contentObserver){this.contentObserver.disconnect();this.contentObserver=null}if(this.priceUpdateInterval){clearInterval(this.priceUpdateInterval);this.priceUpdateInterval=null}if(this.preventScrollHandler){document.removeEventListener("touchmove",this.preventScrollHandler);document.removeEventListener("wheel",this.preventScrollHandler);this.preventScrollHandler=null}}show(){this.openModal()}hide(){this.closeModal()}resetSession(){sessionStorage.removeItem("filterModalShown");this.hasShownOnLoad=false}}let carsFilterModal;document.addEventListener("DOMContentLoaded",()=>{setTimeout(()=>{carsFilterModal=new CarsFilterModal},100)});window.CarsFilterModal=CarsFilterModal;window.applyModalFilter=function(filterType){document.querySelectorAll('input[name="price-category"]').forEach(radio=>{radio.checked=false});document.querySelectorAll('input[name="mobile-price-category"]').forEach(radio=>{radio.checked=false});const filterMap={econom:"economy",standard:"standard",premium:"premium",all:"all"};const priceCategory=filterMap[filterType]||"all";const desktopRadio=document.querySelector(`input[name="price-category"][value="${priceCategory}"]`);if(desktopRadio){desktopRadio.checked=true}const mobileRadio=document.querySelector(`input[name="mobile-price-category"][value="${priceCategory}"]`);if(mobileRadio){mobileRadio.checked=true}const params=new URLSearchParams;const existingParams=new URLSearchParams(window.location.search);for(const[key,value]of existingParams){if(key!=="min_price"&&key!=="max_price"){params.set(key,value)}}const priceSettings=window.carsFilterModal?.priceFilterSettings||{economy:{min:0,max:30},standard:{min:31,max:60},premium:{min:61,max:999}};if(priceCategory&&priceCategory!=="all"){const settings=priceSettings[priceCategory];if(settings){params.set("min_price",settings.min);params.set("max_price",settings.max)}}const newUrl=window.location.pathname+(params.toString()?"?"+params.toString():"");window.history.pushState({},"",newUrl);if(typeof fetchAndRenderCars==="function"){fetchAndRenderCars()}else if(typeof updateFiltersAndFetch==="function"){updateFiltersAndFetch()}else{window.location.reload()}if(window.carsFilterModal&&window.carsFilterModal.modal){window.carsFilterModal.modal.querySelectorAll(".filter-card").forEach(card=>{card.classList.remove("selected")});const selectedCard=window.carsFilterModal.modal.querySelector(`.filter-card[data-filter="${filterType}"]`);if(selectedCard){selectedCard.classList.add("selected")}}};